$ErrorActionPreference='Stop';$Mode=if($Mode -ieq 'Prepare'){'Prepare'}else{'Run'};$Configuration=if($Configuration -ieq 'DebugCPU'){'DebugCPU'}else{'ReleaseCPU'};$Case=@{nonfixeddrain='NonFixedDrain';loadedvariable='LoadedVariable';bottomnoslip='BottomNoSlip'}[$Case.ToLowerInvariant()];$tests=Split-Path -Parent $PSScriptRoot;$repo=(Get-Item -LiteralPath $tests).Parent.Parent.Parent.Parent.FullName;$logs=Join-Path $tests 'logs';$src=Join-Path $repo 'src';$seed=Join-Path $tests 'outputs\upl_column_public_reject_seed_r1';$manifest=Join-Path $logs 'upl_column_public_reject_r1.inputs.json'
function E([string]$p){$f=Get-Item -LiteralPath $p;[ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
