if($Mode -ceq 'Prepare'){
  Fresh @($seed,$manifest);$parentPath=Join-Path $logs 'upl_column_public_r1.inputs.json';$parent=J $parentPath;Need ($parent.passed -and $parent.prepared -and !$parent.physical_acceptance) 'Passed public-input preparation required';$jobs=@($parent.jobs|Where-Object {$_.window -ceq 'smoke'});Need ($jobs.Count -eq 1) 'One sealed public smoke seed required';$base=$jobs[0]
