    $prefix=Join-Path $seed ('upl_column_public_reject_'+$c.name+'_r1');$xml=$prefix+'.xml';$bi4=$prefix+'.bi4';$normal=$prefix+'_Normals.nbi4';Fresh @($xml,$bi4,$normal);$settings=New-Object Xml.XmlWriterSettings;$settings.Encoding=New-Object Text.UTF8Encoding($false);$settings.Indent=$false;$settings.NewLineHandling=[Xml.NewLineHandling]::None;$w=[Xml.XmlWriter]::Create($xml,$settings);try{$d.Save($w)}finally{$w.Dispose()}
    $back=Dom $xml;foreach($change in $edits){(Node $back $change.xpath).SetAttribute('value',$change.before)};Need ($back.OuterXml -ceq $original.OuterXml) 'Only declared unsupported fields and zero-duration cap may differ'
    Copy-Item -LiteralPath $base.initial_BI4.path -Destination $bi4;Copy-Item -LiteralPath $base.normals.path -Destination $normal;$be=E $bi4;$ne=E $normal;Need ($be.sha256 -ceq $base.initial_BI4.sha256 -and $ne.sha256 -ceq $base.normals.sha256) 'Retained binary copy differs';$xe=E $xml;$files+=@($xe,$be,$ne);$newJobs+=@{name=$c.name;runtime=$xe;initial_BI4=$be;normals=$ne;input_prefix=$prefix;edits=$edits;inverse_DOM_exact=$true;expected_method=$c.method;expected_message=$c.message;slip_argument=$c.slip;expected_exit_code=1;duration_s=0}
  }}catch{$failure=$_.Exception.Message};try{V $bindings;V $files}catch{if(!$failure){$failure=$_.Exception.Message}};$ok=(!$failure -and $newJobs.Count -eq 3 -and $files.Count -eq 9)
  Save $manifest ([ordered]@{stage='upl_column_public_reject_prepare_r1';passed=[bool]$ok;prepared=[bool]$ok;jobs=$newJobs;inputs=$bindings;files=$files;parent=(E $parentPath);source_seed=@($base.runtime,$base.initial_BI4,$base.normals);solver_build_reader_invoked=$false;physical_acceptance=$false;failure=$failure});if(!$ok){throw 'Negative-input Prepare failed; preserve partials and false manifest'};Write-Output 'Three unsupported zero-duration inputs prepared; no program run';exit 0
}
$tag='upl_column_public_reject_'+$Case+'_'+$Configuration+'_r1';$out=Join-Path $tests ('outputs\'+$tag);$record=Join-Path $logs ($tag+'.check.json');$callPath=Join-Path $logs ($tag+'.call.json');$log=Join-Path $logs ($tag+'.log');Fresh @($out,$record,$callPath,$log)
$prep=J $manifest;Need ($prep.passed -and $prep.prepared -and @($prep.jobs).Count -eq 3) 'Own negative-input preparation required';$rows=@($prep.jobs|Where-Object {$_.name -ceq $Case});Need ($rows.Count -eq 1) 'One selected negative case required';$job=$rows[0];$declaration=@($cases|Where-Object {$_.name -ceq $Case})[0];Need ($job.inverse_DOM_exact -and $job.duration_s -eq 0 -and $job.expected_exit_code -eq 1 -and $job.expected_method -ceq $declaration.method -and $job.expected_message -ceq $declaration.message -and $job.slip_argument -ceq $declaration.slip) 'Selected rejection contract differs'
$buildPath=Join-Path $logs $(if($Configuration -ceq 'DebugCPU'){'upl_column_public_default_DebugCPU_r1.build.json'}else{'upl_column_public_ReleaseCPU_r1.build.json'});$b=J $buildPath
Need ($b.passed -and $b.configuration -ceq $Configuration -and $b.default_CPU_solution_build_with_isolated_outputs -and $b.direct_native_call -and $b.typed_LASTEXITCODE_captured_immediately -and $b.owned_call_exited -and $b.exit_code -is [int] -and $b.exit_code -eq 0 -and $b.source_bindings_unchanged -and $b.canonical_programs_unchanged -and @($b.objects).Count -eq 86 -and @($b.source_snapshot).Count -eq 265 -and @($b.canonical_programs_before).Count -eq 7 -and !$b.helper_built -and !$b.canonical_program_installed) 'Current isolated authoritative CPU86 project-main build required'
$d=$b;$adopted=$null;if($Configuration -ceq 'ReleaseCPU'){$adopted=$b.adopted_Debug_source_build;V @($adopted);$d=J $adopted.path;Need ($d.passed -and $d.configuration -ceq 'DebugCPU' -and $d.source_bindings_unchanged -and $d.runtime_unchanged) 'Release adopted same-round Debug doc/runtime authority required'}
Need (@($d.runtime_before).Count -eq 4 -and $d.documentation_snapshot.original.path -and $d.documentation_snapshot.snapshot.path) 'Actual doc/runtime schema required';$inputs=$author+@((E $manifest),(E $buildPath),$b.program,$b.log,$b.binlog,$job.runtime,$job.initial_BI4,$job.normals)+@($prep.inputs)+@($b.tools)+@($b.author_files)+@($b.objects)+@($b.canonical_programs_before)+@($d.runtime_before)+@($d.documentation_snapshot.original,$d.documentation_snapshot.snapshot);if($adopted){$inputs+=@($adopted)}
foreach($p in $b.source_snapshot){Need ($p.original.bytes -eq $p.snapshot.bytes -and $p.original.sha256 -ieq $p.snapshot.sha256) 'Current source snapshot differs';$inputs+=@($p.original,$p.snapshot)}
$prefix=Join-Path (Split-Path -Parent $job.runtime.path) ([IO.Path]::GetFileNameWithoutExtension($job.runtime.path));Need ($prefix -ceq $job.input_prefix -and $prefix+'.xml' -ceq $job.runtime.path) 'Exact runtime prefix differs';$runtime=@();V $inputs
foreach($e in $d.runtime_before){$copy=Join-Path (Split-Path -Parent $b.program.path) ([IO.Path]::GetFileName($e.path));$copied=$false;if(!(Test-Path -LiteralPath $copy)){Copy-Item -LiteralPath $e.path -Destination $copy;$copied=$true};$ce=E $copy;Need ($ce.bytes -eq $e.bytes -and $ce.sha256 -ieq $e.sha256) 'Executable-directory runtime differs; never overwrite';$runtime+=@{original=$e;copy=$ce;copied_by_this_action=$copied}}
function Verify{V $inputs;V $prep.files;foreach($p in $runtime){V @($p.original,$p.copy)}}
$argv=@('-cpu','-ompthreads:1','-stable',$job.slip_argument,$prefix,$out,'-dirdataout','data','-svres');Verify;[IO.File]::WriteAllBytes($log,[byte[]]@());$started=[DateTime]::UtcNow.ToString('o');$code=$null;$launchFailure=$null;$saved=$ErrorActionPreference;Push-Location $src
try{$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;& $b.program.path @argv 2>&1|Tee-Object -FilePath $log -Append|Out-Host;$code=$LASTEXITCODE}catch{$launchFailure=$_.Exception.Message}finally{Pop-Location;$ErrorActionPreference=$saved}
Save $callPath ([ordered]@{program=$b.program;arguments=$argv;working_directory=$src;started_utc=$started;ended_utc=[DateTime]::UtcNow.ToString('o');direct_native_call=$true;typed_LASTEXITCODE_captured_immediately=($code -is [int]);owned_call_exited=($code -is [int]);exit_code=$code;invocation_failure=$launchFailure;log=(E $log);public_project_main=$true;fixture_or_Run_override=$false;expected_exit_code=1;zero_duration_input=$true;physical_acceptance=$false})
