try{Verify;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}};if(Test-Path -LiteralPath $out){$files=@(Get-ChildItem -LiteralPath $out -File -Recurse|Sort-Object FullName|ForEach-Object {E $_.FullName})};$ok=(!$failure -and $unchanged -and $matched -and $noLoop -and $code -is [int] -and $code -eq 1 -and $numbered.Count -eq 0)
Save $record ([ordered]@{stage='upl_column_public_reject_r1';passed=[bool]$ok;case=$Case;configuration=$Configuration;source_build=(E $buildPath);adopted_Debug_source_build=$adopted;program=$b.program;input_manifest=(E $manifest);runtime_input=$job.runtime;call=(E $callPath);inputs=$inputs;runtime=$runtime;files=$files;expected_method=$job.expected_method;expected_message=$job.expected_message;expected_exact_exception_observed=$matched;owned_typed_exit1_observed=($code -is [int] -and $code -eq 1);numbered_PART_frames=$numbered.Count;pre_integration_loop_rejection=$noLoop;source_input_program_runtime_canonical_unchanged=$unchanged;zero_duration_input=$true;physical_trajectory_completed=$false;new_GenCase_build_reader_or_old_control_invoked=$false;physical_acceptance=$false;failure=$failure});if(!$ok){throw "Rejection check failed; preserve $record, no retry or acceptance fallback"};Write-Output "One bounded public rejection sealed: $record"
